/* Local visual prototype. All mutations are in memory and reset on reload. */
(() => {
  'use strict';
  const initial = window.RYADOM_DEMO;
  const state = {
    data: JSON.parse(JSON.stringify(initial)), actor: null, preview: 'DEFAULT',
    step: 1, draft: {}, questions: {}, returnTo: null, myTab: 'confirmed',
  };
  const main = document.querySelector('#main');
  const modal = document.querySelector('#modal');
  let toastTimer;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const paths = {
    arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>', back: '<path d="m14 6-6 6 6 6"/>',
    search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    pin: '<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.2"/>',
    calendar: '<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1"/>',
    clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',
    users: '<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2m2-16a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',
    user: '<circle cx="12" cy="8" r="4"/><path d="M4 21v-1a8 8 0 0 1 16 0v1"/>',
    plus: '<path d="M12 5v14M5 12h14"/>', check: '<path d="m5 12 4 4L19 6"/>',
    close: '<path d="m6 6 12 12M6 18 18 6"/>', info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',
    filter: '<path d="M4 6h16M7 12h10m-7 6h4"/>', chat: '<path d="M21 11a9 9 0 0 1-9 9H4l-2 2V11a9.5 9.5 0 0 1 19 0Z"/><path d="M7 10h10m-10 4h7"/>',
    run: '<circle cx="15" cy="4" r="2"/><path d="m12 8 4 4 5-1M12 8l-4 5 5 3-3 6M12 8 7 8l-3 4m9 4 5 2 1 4"/>',
    tennis: '<ellipse cx="14.5" cy="8.5" rx="5" ry="7" transform="rotate(40 14.5 8.5)"/><path d="m11 14-8 8m2-6 3 3m4-14 7 6m-9-3 6 6"/>',
    chess: '<path d="M6 21h12l-2-4H8l-2 4Zm2-4 2-7H8V6h8v4h-2l2 7M8 6V3m4 3V2m4 4V3"/>',
    ball: '<circle cx="12" cy="12" r="9"/><path d="m12 8 4 3-1 5H9l-1-5 4-3Zm0 0V3m4 8 5-2m-6 7 3 4m-9-4-3 4m2-9L3 9"/>',
    stretch: '<circle cx="12" cy="4" r="2"/><path d="M12 8v7m0-5L4 7m8 3 8-3m-8 8-5 7m5-7 5 7"/>',
    target: '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  };
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.arrow}</svg>`;
  const mark = '<svg class="brand-mark" viewBox="0 0 64 64" aria-hidden="true"><path d="M13 49 27 15m10 34 14-34" fill="none" stroke="currentColor" stroke-width="12" stroke-linecap="round"/></svg>';
  const logo = () => `<a class="brand" href="#/" aria-label="Рядом — главная">${mark}<span>рядом</span></a>`;
  const person = id => state.data.people[id] || {name:'Участник',initials:'У'};
  const avatar = (id, extra = '') => `<span class="avatar ${extra}" aria-hidden="true">${esc(person(id).initials)}</span>`;
  const orgAvatar = (large = false) => `<span class="avatar organization ${large ? 'large' : ''}" aria-hidden="true">Т</span>`;
  const date = event => new Intl.DateTimeFormat('ru-RU', {day:'numeric',month:'long',timeZone:'Asia/Krasnoyarsk'}).format(new Date(event.date));
  const time = event => new Intl.DateTimeFormat('ru-RU', {hour:'2-digit',minute:'2-digit',timeZone:'Asia/Krasnoyarsk'}).format(new Date(event.date));
  const fullDate = event => new Intl.DateTimeFormat('ru-RU', {weekday:'short',day:'numeric',month:'long',timeZone:'Asia/Krasnoyarsk'}).format(new Date(event.date));
  const getRoute = () => new URL(location.hash.startsWith('#/') ? location.hash.slice(1) : '/', 'http://prototype.local');
  const eventById = id => state.data.events.find(e => e.id === id);
  const ownerName = e => e.organization ? 'Сообщество «Темп»' : person(e.owner).name;
  const ownerLink = e => e.organization ? '#/organizations/temp' : `#/people/${encodeURIComponent(e.owner)}`;
  const confirmed = e => e.participants.filter(p => p.status === 'CONFIRMED');
  const ownParticipation = e => e.participants.find(p => p.user === state.actor);
  const badge = (text, tone = '', glyph = '') => `<span class="badge ${tone}">${glyph ? icon(glyph) : ''}${esc(text)}</span>`;
  const paragraphs = text => esc(text).split('\n\n').map(p => `<p>${p}</p>`).join('');
  const notify = text => {
    const el = document.querySelector('#toast'); el.textContent = text; el.hidden = false;
    clearTimeout(toastTimer); toastTimer = setTimeout(() => { el.hidden = true; }, 4200);
  };
  const go = path => {
    if(getRoute().pathname==='/events/new'&&path!=='/events/new'&&state.draft.title){
      modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">Выйти из создания?</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><p class="modal-note">Заполненная встреча ещё не опубликована. При уходе данные формы будут потеряны.</p><div class="form-actions"><button class="btn secondary" data-action="close-modal">Остаться</button><button class="btn" data-action="leave-form" data-path="${esc(path)}">Выйти</button></div>`;
      modal.showModal();return;
    }
    if (getRoute().pathname + getRoute().search === path) render(); else location.hash = path;
  };
  const breadcrumb = (text, href = '#/events', backText = 'Все встречи') => `<nav class="breadcrumbs" aria-label="Навигационная цепочка"><a href="${href}">${icon('back')}${esc(backText)}</a><span>/</span><span>${esc(text)}</span></nav>`;
  const empty = (title, desc, action = '<a class="btn" href="#/events">Найти встречу</a>') => `<div class="empty">${icon('search')}<h2>${esc(title)}</h2><p>${esc(desc)}</p>${action}</div>`;
  function artwork(e, large = false) {
    const graphics = e.icon === 'chess' ? '<g fill="currentColor" opacity=".12"><path d="M180 0h50v50h-50zm100 0h50v50h-50zm-50 50h50v50h-50zm100 0h50v50h-50zm-150 50h50v50h-50zm100 0h50v50h-50z"/></g><g transform="translate(250 15) scale(4)" fill="none" stroke="currentColor" stroke-width="1.3">'+paths.chess+'</g>' : e.icon === 'tennis' || e.icon === 'ball' ? '<g fill="none" stroke="currentColor" opacity=".2" stroke-width="1"><rect x="130" y="-25" width="220" height="190" rx="4"/><path d="M130 70h220m-110-95v190m-110-155h220M130 135h220m50-125v125m120-125v125"/></g><g transform="translate(255 24) scale(3.5)" fill="none" stroke="currentColor" stroke-width="1.3">'+paths[e.icon]+'</g>' : '<g fill="none" stroke="currentColor"><path d="M110 170C150 80 180 165 245 58S355-10 420 40" stroke-width="30" opacity=".08"/><path d="M80 170C130 60 200 170 255 50S355 0 420 20" stroke-width="1.5" opacity=".25" stroke-dasharray="6 6"/></g><g transform="translate(255 22) scale(3.6)" fill="none" stroke="currentColor" stroke-width="1.3">'+paths[e.icon]+'</g>';
    return `<div class="event-art art-${esc(e.id)} ${large ? 'detail-art' : ''}" aria-hidden="true"><svg viewBox="0 0 400 150" preserveAspectRatio="xMidYMid slice">${graphics}</svg><span class="art-type">${esc(e.sport.toUpperCase())}</span></div>`;
  }
  function eventCard(e) {
    return `<article class="event-card"><a href="#/events/${encodeURIComponent(e.id)}" aria-label="${esc(e.title)}">${artwork(e)}<div class="event-body"><h3>${esc(e.title)}</h3><div class="event-meta">${icon('calendar')}${esc(fullDate(e))} · ${esc(time(e))}</div><div class="event-meta">${icon('pin')}${esc(e.place)}</div><p class="tagline">${esc(e.tagline || 'В своём темпе, вместе с другими')}</p></div></a><div class="event-bottom"><a class="owner-label" href="${ownerLink(e)}">${e.organization ? orgAvatar() : avatar(e.owner, 'warm')}<span>${esc(e.organization ? 'Темп' : person(e.owner).name.split(' ')[0])}</span></a><span class="mode-label">${icon(e.mode === 'OPEN' ? 'check' : 'clock')}${e.mode === 'OPEN' ? 'Свободная запись' : 'По заявке'}</span></div></article>`;
  }
  function renderChrome(route) {
    const isEvent = /^\/events\/[^/]+$/.test(route.pathname) && route.pathname !== '/events/new';
    const screens = [['/','Главная'],['/events','Каталог'],['/events/run','Мероприятие'],['/people/anna','Профиль человека'],['/organizations/temp','Организация'],['/events/new','Создание встречи']];
    const selection = isEvent ? '/events/run' : route.pathname;
    document.querySelector('#prototype-bar').innerHTML = `<div class="prototype-bar"><div class="container prototype-inner"><span class="prototype-caption"><i class="proto-dot"></i><strong>ДИЗАЙН 01</strong><span class="prototype-long">Данные вымышлены · изменения до перезагрузки</span><span class="prototype-short">/ РЯДОМ</span></span><div class="prototype-controls"><label><span>Экран</span><select aria-label="Экран прототипа" data-action="screen">${screens.map(([path,title])=>`<option value="${path}" ${selection === path ? 'selected' : ''}>${title}</option>`).join('')}</select></label>${isEvent ? `<label><span>Состояние</span><select aria-label="Состояние встречи" data-action="preview">${[['DEFAULT','Обычное'],['PENDING','Заявка отправлена'],['CONFIRMED','Ты участвуешь'],['REJECTED','Заявка отклонена'],['UNPUBLISHED','Публикация снята'],['ERROR','Ошибка загрузки'],['LOADING','Загрузка']].map(([id,label])=>`<option value="${id}" ${state.preview === id ? 'selected' : ''}>${label}</option>`).join('')}</select></label>` : ''}<button class="proto-reset" data-action="reset">Сбросить</button></div></div></div>`;
    document.querySelector('#site-header').innerHTML = `<div class="container"><header class="site-header">${logo()}<nav class="header-nav" aria-label="Основная навигация"><a href="#/events" class="${route.pathname.startsWith('/events') ? 'active' : ''}">Встречи</a><a href="#/organizations/temp">Сообщество «Темп»</a></nav><div class="header-right"><a class="text-link create-header" href="#/events/new">${icon('plus')}Создать встречу</a>${state.actor ? `<a href="#/me" aria-label="Личный кабинет: ${esc(person(state.actor).name)}">${avatar(state.actor,'warm')}</a>` : '<button class="btn secondary" data-action="login">Войти</button>'}</div></header></div>`;
    document.querySelector('#site-footer').innerHTML = `<footer class="site-footer"><div class="container footer-inner">${logo()}<span>Есть планы. Будет компания.</span><p class="footer-note">Дизайн-прототип · версия 0.1<br>Профили, сообщества и встречи вымышлены.</p></div></footer>`;
    document.querySelector('#mobile-nav').innerHTML = `<nav class="mobile-nav" aria-label="Мобильная навигация"><a href="#/events" class="${route.pathname.startsWith('/events') ? 'active' : ''}">${icon('search')}Встречи</a><a href="#/me/events" class="${route.pathname === '/me/events' ? 'active' : ''}">${icon('calendar')}Мои встречи</a><a href="#/me" class="${route.pathname === '/me' ? 'active' : ''}">${icon('user')}Профиль</a></nav>`;
  }
  function searchForm(query = '', city = 'Красноярск') {
    return `<form class="search-box" data-form="search"><label class="search-field">${icon('search')}<div><span>Что хочется делать?</span><input type="search" name="q" aria-label="Название или интерес" placeholder="Бег, теннис, шахматы…" value="${esc(query)}"></div></label><label class="search-field">${icon('pin')}<div><span>Где встречаемся?</span><input name="city" aria-label="Город" placeholder="Город" value="${esc(city)}"></div></label><button class="btn" type="submit">Найти встречу ${icon('arrow')}</button></form>`;
  }
  function home() {
    const heroArt = `<div class="hero-art"><div class="art-caption">В СВОЁМ ТЕМПЕ<span>Но с хорошей компанией</span></div><svg viewBox="0 0 500 354" aria-hidden="true"><g fill="none" stroke="#fff" opacity=".2"><circle cx="345" cy="130" r="145"/><circle cx="345" cy="130" r="108"/><circle cx="345" cy="130" r="72"/></g><g fill="none" stroke="#fff" stroke-width="38" stroke-linecap="round"><path d="m153 231 63-154m31 154 63-154"/></g><circle cx="352" cy="232" r="10" fill="#17191D"/><circle cx="369" cy="210" r="5" fill="#fff"/><path d="M44 248c88-1 98-78 160-74s71 78 139 58" fill="none" stroke="#fff" stroke-dasharray="3 7" stroke-linecap="round"/></svg><div class="art-note"><span class="art-note-icon">${icon('run')}</span><div><strong>Бежим вдоль Енисея</strong><small>Суббота, 24 октября · 09:00</small></div>${icon('arrow')}</div></div>`;
    return `<div class="container"><section class="hero"><div><p class="eyebrow">Совместные занятия и встречи</p><h1>Есть планы.<br>Найдётся<br><span class="red">компания.</span></h1><p class="hero-description">Пробежка у реки, партия в шахматы или первая подача. Найди людей, с которыми захочется начать.</p><div class="hero-actions"><a class="btn" href="#/events">Выбрать встречу ${icon('arrow')}</a><a class="text-link" href="#/events/new">Или создать свою ${icon('plus')}</a></div></div>${heroArt}</section>${searchForm()}<nav class="category-row" aria-label="Спортивные направления">${[['run','Бег'],['tennis','Теннис'],['chess','Шахматы'],['ball','Волейбол'],['stretch','Зарядка']].map(([glyph,sport])=>`<a class="chip" href="#/events?sport=${encodeURIComponent(sport)}">${icon(glyph)}${sport}</a>`).join('')}</nav><section class="section"><div class="section-head"><div><h2>Ближайшие встречи</h2><p>Разные занятия. Один повод собраться.</p></div><a class="text-link" href="#/events">Все встречи ${icon('arrow')}</a></div><div class="event-grid">${state.data.events.slice(0,3).map(eventCard).join('')}</div></section><section class="steps-section"><p class="eyebrow red">От желания — к встрече</p><div class="how-grid">${[['01','Найди своё','Выбери занятие, время и место, которые тебе подходят.'],['02','Договорись','Посмотри условия или задай организатору вопрос.'],['03','Встречайтесь','Присоединяйся сразу или дождись подтверждения заявки.']].map(([n,title,body])=>`<div class="how-item"><span class="step-number">${n}</span><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div></section><section class="community-invite"><div><h2>Уже собираете людей?</h2><p>Познакомьтесь с сообществом «Темп» и посмотрите, как могут выглядеть встречи вашего клуба.</p></div><a class="btn secondary" href="#/organizations/temp">Страница сообщества ${icon('arrow')}</a></section></div>`;
  }
  function catalog(route) {
    const q=route.searchParams.get('q')||'', city=route.searchParams.get('city')??'Красноярск', sport=route.searchParams.get('sport')||'', mode=route.searchParams.get('mode')||'', day=route.searchParams.get('day')||'';
    const events=state.data.events.filter(e=>(!q || `${e.title} ${e.sport} ${e.description}`.toLocaleLowerCase('ru').includes(q.toLocaleLowerCase('ru')))&&(!city||e.city.toLocaleLowerCase('ru')===city.toLocaleLowerCase('ru').trim())&&(!sport||sport===e.sport)&&(!mode||mode===e.mode)&&(!day||e.date.slice(0,10)===day)).sort((a,b)=>a.date.localeCompare(b.date));
    const sportOptions=[...new Set(state.data.events.map(e=>e.sport))];
    return `<div class="container page"><div class="page-intro"><div><p class="eyebrow red form-eyebrow">Встречаемся рядом</p><h1>Найди свои планы</h1><p>Выбери занятие — компания уже собирается.</p></div><a class="btn secondary" href="#/events/new">${icon('plus')}Создать встречу</a></div><div class="catalog-search">${searchForm(q,city)}</div><div class="catalog-layout"><details class="filter-panel" ${innerWidth>=768?'open':''}><summary>${icon('filter')}Фильтры ${[sport,mode,day].filter(Boolean).length ? `· ${[sport,mode,day].filter(Boolean).length}`:''}</summary><form class="filter-content" data-form="filters"><div class="filter-group"><h3>Направление</h3><label><input type="radio" name="sport" value="" ${!sport?'checked':''}>Все направления</label>${sportOptions.map(s=>`<label><input type="radio" name="sport" value="${esc(s)}" ${sport===s?'checked':''}>${esc(s)}</label>`).join('')}</div><div class="filter-group"><h3>Как присоединиться</h3><label><input type="radio" name="mode" value="" ${!mode?'checked':''}>Любой способ</label><label><input type="radio" name="mode" value="OPEN" ${mode==='OPEN'?'checked':''}>Свободно</label><label><input type="radio" name="mode" value="APPROVAL" ${mode==='APPROVAL'?'checked':''}>По заявке</label></div><div class="filter-group"><h3><label for="date-filter">Дата встречи</label></h3><input type="date" name="day" id="date-filter" value="${esc(day)}"></div><button class="btn subtle wide" type="button" data-action="clear-filters">Сбросить фильтры</button></form></details><div><div class="result-line"><span>Найдено встреч: ${events.length}</span><span>По дате начала</span></div>${events.length?`<div class="event-grid">${events.map(eventCard).join('')}</div>`:empty('Пока ничего не нашлось','Попробуй другое направление, город или дату. Или создай свою встречу.','<button class="btn" data-action="clear-filters">Сбросить поиск</button>')}</div></div></div>`;
  }
  function eventPage(e) {
    if (state.preview==='LOADING') return `<div class="container page">${breadcrumb('Встреча')}<div role="status" aria-label="Загружаем встречу"><div class="skeleton title"></div><div class="skeleton line"></div><div class="skeleton block"></div><div class="skeleton line"></div><p class="muted small">Загружаем встречу…</p></div></div>`;
    if (state.preview==='ERROR') return `<div class="container page">${breadcrumb('Встреча')}${empty('Не удалось загрузить встречу','Проверь соединение и попробуй ещё раз.','<button class="btn" data-action="retry">Попробовать снова</button>')}</div>`;
    if (state.preview==='UNPUBLISHED') return `<div class="container page">${breadcrumb(e.title)}<div class="page-intro"><h1>${esc(e.title)}</h1></div><div class="notice neutral">${icon('info')}<div><strong>Публикация недоступна</strong>Присоединиться, отправить заявку или новый вопрос больше нельзя.</div></div>${state.actor===e.owner?'<p class="small muted" style="margin-top:20px">Причина снятия: условия встречи требуют уточнения.</p>':'<p class="small muted" style="margin-top:20px">Состояние прежней записи сохранено. Доступность встречи изменилась.</p>'}<a class="text-link" href="#/events">Посмотреть другие встречи ${icon('arrow')}</a></div>`;
    const own=state.actor===e.owner, status=state.preview!=='DEFAULT'?state.preview:ownParticipation(e)?.status;
    const title=status==='CONFIRMED'?'Ты участвуешь':status==='PENDING'?'Заявка отправлена':status==='REJECTED'?'Заявка отклонена':e.mode==='OPEN'?'Присоединяйся':'Встреча по заявке';
    const statusText=status==='CONFIRMED'?'До встречи! Всё о времени и месте — ниже.':status==='PENDING'?'Ожидаем решение организатора. Пока участие не подтверждено.':status==='REJECTED'?'В этот раз участие не подтверждено. Можно выбрать другую встречу.':e.mode==='OPEN'?'Запись сразу подтверждается. Отдельного одобрения не нужно.':'Организатор рассмотрит заявку и подтвердит участие.';
    const noticeTone=status==='CONFIRMED'?'success':status==='PENDING'?'info':status==='REJECTED'?'error':'';
    return `<div class="container page">${breadcrumb(e.title)}<div class="event-heading">${badge(e.sport,'',e.icon)}<h1 class="detail-title">${esc(e.title)}</h1><div class="detail-info"><span>${icon('calendar')}${esc(fullDate(e))} · ${time(e)}</span><span>${icon('pin')}${esc(e.city)}, ${esc(e.place)}</span></div></div><div class="detail-layout"><div class="detail-content">${artwork(e,true)}<section class="detail-section"><h2>О встрече</h2>${paragraphs(e.description)}</section><section class="detail-section"><h2>Что нужно знать</h2><div class="info-line">${icon('check')}<p>${esc(e.conditions)}</p></div></section><section class="detail-section"><h2>Где встречаемся</h2><div class="info-line">${icon('pin')}<div><p><strong>${esc(e.place)}</strong></p><p class="muted">${esc(e.meetingPoint)}</p></div></div></section><section class="detail-section" id="discussion"><div class="section-head"><h2>Обсуждение</h2><span class="muted small">${e.messages.length} сообщений</span></div><p class="muted">Хочешь уточнить условия? Вопрос можно задать и до записи.</p>${e.messages.length?e.messages.map(m=>`<article class="discussion-message">${avatar(m.user,m.user===e.owner?'warm':'blue')}<div><div class="message-author"><a href="#/people/${encodeURIComponent(m.user)}">${esc(person(m.user).name)}</a>${m.user===e.owner?badge('Организатор'):''}<time>${esc(m.time)}</time></div><p>${esc(m.body)}</p></div></article>`).join(''):'<p class="muted" style="margin-top:20px">Здесь пока нет вопросов. Можно задать первый.</p>'}<form class="question-form" data-form="question" data-event="${e.id}"><label class="field"><span>Твой вопрос</span><textarea name="body" maxlength="4000" required placeholder="Например, можно ли прийти без опыта?">${esc(state.questions[e.id]||'')}</textarea></label><div class="question-actions"><p class="small muted">${state.actor?'Пиши по делу и уважай других участников.':'Войди, чтобы отправить вопрос организатору.'}</p><button class="btn" type="submit">${state.actor?'Задать вопрос':'Войти и задать вопрос'} ${icon('arrow')}</button></div></form></section></div><aside class="join-panel" aria-label="Участие во встрече">${badge(e.mode==='OPEN'?'Свободная запись':'По заявке',e.mode==='APPROVAL'?'info':'',e.mode==='OPEN'?'check':'clock')}<h2>${own?'Ты организуешь эту встречу':title}</h2><p class="small muted">${own?'Состав и заявки участников доступны в управлении встречей.':statusText}</p>${own?`<a class="btn wide" href="#/events/${e.id}/manage">Участники и заявки</a>`:status?`<div class="notice ${noticeTone}" style="margin-top:18px">${icon(status==='CONFIRMED'?'check':status==='PENDING'?'clock':'info')}<span>${status==='CONFIRMED'?'Участие подтверждено':status==='PENDING'?'Ожидает решения':'Участие не подтверждено'}</span></div>${status==='REJECTED'?'<a class="text-link" href="#/events">Другие встречи '+icon('arrow')+'</a>':''}`:`<button class="btn wide" data-action="join" data-id="${e.id}">${e.mode==='OPEN'?'Присоединиться':'Подать заявку'} ${icon('arrow')}</button>`}<div class="people-line"><div class="avatar-stack">${confirmed(e).slice(0,3).map(p=>avatar(p.user,'warm')).join('')}</div><span>${confirmed(e).length} в составе участников</span></div><div class="join-divider"></div><p class="date-big">${esc(date(e))}</p><p class="time">${time(e)} · Красноярск, UTC+7</p><p class="small">${esc(e.place)}</p><div class="join-divider"></div><p class="eyebrow muted" style="font-size:9px;margin-bottom:13px">Организатор</p><a class="organizer-mini" href="${ownerLink(e)}">${e.organization?orgAvatar():avatar(e.owner,'warm')}<span><strong>${esc(e.organization?'Темп':person(e.owner).name)}</strong><span class="muted small">${e.organization?'Спортивное сообщество':'Участник Рядом'}</span></span>${icon('arrow')}</a></aside></div></div>`;
  }
  function profile(id, organization = false) {
    const p=person(id), org=state.data.organization;
    const events=state.data.events.filter(e=>organization?e.organization==='temp':e.owner===id&&!e.organization);
    const sports=organization?org.interests:[...new Set(events.map(e=>e.sport))];
    return `<div class="container page">${breadcrumb(organization?'Сообщество «Темп»':p.name)}<div class="profile-cover ${organization?'org-cover':''}" aria-hidden="true"></div><section class="profile-header">${organization?orgAvatar(true):avatar(id,'large warm')}<div class="profile-info"><h1>${esc(organization?'Темп':p.name)}</h1><p class="small muted">${organization?'Спортивное сообщество':'Участник Рядом'}</p></div>${organization?badge('Допущена к публикации','success','check'):state.actor===id?'<a class="btn secondary" href="#/me">Мой кабинет</a>':''}</section><div class="profile-content"><aside class="profile-aside"><h2>${organization?'О сообществе':'Встречаемся за занятием'}</h2><p>${organization?esc(org.description):'Открой встречу, чтобы узнать условия и познакомиться с организатором в обсуждении.'}</p>${sports.length?`<h2 style="margin-top:25px">${organization?'Спортивные интересы':'Направления встреч'}</h2><div class="interest-list">${sports.map(s=>`<a class="chip" href="#/events?sport=${encodeURIComponent(s)}">${esc(s)}</a>`).join('')}</div>`:''}${organization?'<p class="preview-only">Допуск означает право публиковать встречи.</p>':''}</aside><div><div class="section-head"><div><h2>${organization?'Встречи сообщества':'Организует встречи'}</h2><p>${events.length?'Выбирай подходящий план и присоединяйся.':'Опубликованные встречи появятся здесь.'}</p></div></div>${events.length?`<div class="event-grid">${events.map(eventCard).join('')}</div>`:empty('Встреч пока нет','Можно найти компанию в каталоге.')}</div></div></div>`;
  }
  function authPrompt(title, text) {
    return `<div class="container page">${breadcrumb(title)}${empty(title,text,'<button class="btn" data-action="login">Войти или зарегистрироваться '+icon('arrow')+'</button>')}</div>`;
  }
  function createPage() {
    if(!state.actor) return authPrompt('Соберём компанию?','Войди, чтобы создать встречу от своего имени.');
    const d=state.draft;
    const val=(name,fallback='')=>esc(d[name]??fallback);
    let body;
    if(state.step===1) body=`<label class="field"><span>Кто организует</span><select class="control" name="organizer"><option value="personal">Я, ${esc(person(state.actor).name)}</option>${state.actor==='anna'?`<option value="temp" ${d.organizer==='temp'?'selected':''}>Сообщество «Темп» · допущено</option>`:''}</select></label><label class="field"><span>Название встречи</span><input name="title" value="${val('title')}" required maxlength="160" placeholder="Например, бежим вдоль реки"><small>Пусть по названию будет понятно, что вы собираетесь делать.</small></label><div class="field-grid"><label class="field"><span>Направление</span><select class="control" name="sport" data-action="draft-sport" required><option value="">Выбери направление</option>${[...new Set(state.data.events.map(e=>e.sport))].map(s=>`<option ${d.sport===s?'selected':''}>${esc(s)}</option>`).join('')}<option value="custom" ${d.sport==='custom'?'selected':''}>Своё направление</option></select></label>${d.sport==='custom'?`<label class="field"><span>Своё направление</span><input name="customSport" value="${val('customSport')}" maxlength="100" required placeholder="Например, фрисби"></label>`:''}</div><label class="field"><span>О встрече</span><textarea name="description" required maxlength="10000" placeholder="Что будете делать, какой темп и кому подойдёт встреча">${val('description')}</textarea></label><div class="field-grid"><label class="field"><span>Дата</span><input type="date" name="date" required value="${val('date')}" min="${new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Krasnoyarsk'}).format(new Date())}"></label><label class="field"><span>Время начала</span><input type="time" name="time" value="${val('time','10:00')}" required><small>Красноярск · UTC+7</small></label></div><label class="field"><span>Город</span><input name="city" required maxlength="120" value="${val('city','Красноярск')}"></label><label class="field"><span>Место встречи</span><input name="place" required maxlength="1000" value="${val('place')}" placeholder="Адрес или понятный ориентир"></label>`;
    else if(state.step===2) body=`<h2 style="font-size:24px;margin-bottom:22px">Как можно присоединиться?</h2><label class="radio-card"><input type="radio" name="mode" value="OPEN" ${d.mode!=='APPROVAL'?'checked':''}><div><strong>Свободная запись</strong><p>Человек сразу становится участником. Не нужно отдельно рассматривать каждую заявку.</p></div></label><label class="radio-card"><input type="radio" name="mode" value="APPROVAL" ${d.mode==='APPROVAL'?'checked':''}><div><strong>По заявке</strong><p>Ты принимаешь или отклоняешь заявки. До решения участие не подтверждено.</p></div></label><label class="field" style="margin-top:28px"><span>Условия участия</span><textarea name="conditions" maxlength="4000" placeholder="Подготовка, одежда или инвентарь. Можно оставить пустым.">${val('conditions')}</textarea><small>Помоги человеку понять, подходит ли ему встреча.</small></label>`;
    else {
      const e=draftEvent();
      body=`<div class="notice neutral" style="margin-bottom:24px">${icon('info')}<div><strong>Всё выглядит правильно?</strong>После публикации встреча появится в каталоге этого макета.</div></div><div class="preview-summary">${artwork(e)}<div><h2>${esc(e.title)}</h2><dl><dt>Организатор</dt><dd>${esc(ownerName(e))}</dd><dt>Когда</dt><dd>${esc(fullDate(e))}, ${time(e)} · UTC+7</dd><dt>Где</dt><dd>${esc(e.city)}, ${esc(e.place)}</dd><dt>Запись</dt><dd>${e.mode==='OPEN'?'Свободная':'По заявке'}</dd><dt>О встрече</dt><dd>${esc(e.description)}</dd><dt>Условия</dt><dd>${esc(e.conditions)}</dd></dl></div></div>`;
    }
    return `<div class="form-page">${breadcrumb('Создать встречу')}<p class="eyebrow red form-eyebrow">Твой повод собраться</p><h1>Новая встреча</h1><p class="form-description">Расскажи о плане. Остальное начнётся со знакомства.</p><div class="wizard-steps" aria-label="Шаги создания">${['О встрече','Участие','Проверка'].map((name,i)=>`<div class="wizard-step ${state.step===i+1?'active':state.step>i+1?'done':''}" ${state.step===i+1?'aria-current="step"':''}><span>${state.step>i+1?'✓':i+1}</span>${name}</div>`).join('')}</div><form data-form="create">${body}<div class="form-actions">${state.step>1?'<button class="btn secondary" type="button" data-action="step-back">Назад</button>':'<span class="small muted">Шаг 1 из 3</span>'}<button class="btn" type="submit">${state.step===3?'Опубликовать встречу':'Продолжить'} ${icon('arrow')}</button></div></form><p class="preview-only">Дизайн-прототип: встреча сохранится только до перезагрузки страницы.</p></div>`;
  }
  function draftEvent() {
    const d=state.draft, sport=d.sport==='custom'?d.customSport:d.sport;
    return {id:'new',title:d.title,sport,icon:({Бег:'run',Теннис:'tennis',Шахматы:'chess',Волейбол:'ball',Зарядка:'stretch'})[sport]||'target',date:`${d.date}T${d.time}:00+07:00`,city:d.city,place:d.place,meetingPoint:d.place,description:d.description,conditions:d.conditions?.trim()||'Дополнительных требований нет.',mode:d.mode||'OPEN',owner:state.actor,organization:d.organizer==='temp'?'temp':null,participants:[],messages:[],tagline:'Новый повод встретиться'};
  }
  function myPage(route) {
    if(!state.actor) return authPrompt('Твои встречи — здесь','Войди, чтобы увидеть участие, заявки и собственные встречи.');
    if(route.pathname==='/me') return `<div class="container page">${breadcrumb('Профиль')}<div class="profile-header" style="margin:20px 0 35px">${avatar(state.actor,'large warm')}<div class="profile-info" style="padding-top:0"><p class="eyebrow muted">Твой профиль</p><h1>${esc(person(state.actor).name)}</h1><a class="text-link" href="#/people/${state.actor}">Публичный профиль ${icon('arrow')}</a></div></div><div class="community-invite"><div><h2>Какие планы?</h2><p>Твои участия, заявки и собственные встречи в одном месте.</p></div><a class="btn" href="#/me/events">Мои встречи ${icon('arrow')}</a></div><div class="section-head"><h2>Собери свою компанию</h2><a class="btn secondary" href="#/events/new">${icon('plus')}Создать встречу</a></div>${state.actor==='anna'?'<a class="text-link" href="#/organizations/temp">Твоё сообщество «Темп» '+icon('arrow')+'</a>':''}<div><button class="text-link" style="background:none;color:var(--muted)" data-action="logout">Выйти из демопрофиля</button></div></div>`;
    const tab=route.searchParams.get('tab')||'confirmed';
    const events=state.data.events.filter(e=>tab==='created'?e.owner===state.actor&&!e.organization:tab==='pending'?['PENDING','REJECTED'].includes(ownParticipation(e)?.status):ownParticipation(e)?.status==='CONFIRMED');
    return `<div class="container page">${breadcrumb('Мои встречи')}<div class="page-intro"><div><h1>Мои встречи</h1><p>Твои планы и всё, что ты организуешь.</p></div><a class="btn secondary" href="#/events/new">${icon('plus')}Создать</a></div><nav class="page-tabs" aria-label="Тип своих встреч">${[['confirmed','Участвую'],['pending','Заявки'],['created','Организую']].map(([id,label])=>`<a href="#/me/events?tab=${id}" class="page-tab ${tab===id?'active':''}">${label}</a>`).join('')}</nav>${events.length?events.map(e=>`<article class="my-row"><a class="row-icon" href="#/events/${e.id}" aria-label="${esc(e.title)}">${icon(e.icon)}</a><div><h3><a href="#/events/${e.id}">${esc(e.title)}</a></h3><p class="small">${esc(fullDate(e))} · ${time(e)} · ${esc(e.place)}</p></div>${tab==='created'?`<a class="btn secondary" href="#/events/${e.id}/manage">Участники и заявки</a>`:badge(ownParticipation(e)?.status==='CONFIRMED'?'Ты участвуешь':ownParticipation(e)?.status==='PENDING'?'На рассмотрении':'Заявка отклонена',ownParticipation(e)?.status==='CONFIRMED'?'success':ownParticipation(e)?.status==='PENDING'?'info':'error')}</article>`).join(''):empty(tab==='created'?'Пока нет своих встреч':'Здесь пока пусто',tab==='created'?'Придумай занятие и пригласи компанию.':'Найди занятие по душе и присоединяйся.',tab==='created'?'<a class="btn" href="#/events/new">Создать встречу</a>':'<a class="btn" href="#/events">Выбрать встречу</a>')}</div>`;
  }
  function manage(e) {
    if(state.actor!==e.owner) return authPrompt('Управление встречей','Для просмотра состава и заявок войди как автор этой встречи.');
    return `<div class="container page">${breadcrumb('Участники и заявки',`#/events/${e.id}`,e.title)}<div class="page-intro"><div><p class="eyebrow red form-eyebrow">Ты организатор</p><h1>${esc(e.title)}</h1><p>Подтверждённые участники и заявки — отдельно.</p></div></div>${['PENDING','CONFIRMED','REJECTED'].map(status=>`<section class="section"><div class="section-head"><h2>${status==='PENDING'?'Заявки':status==='CONFIRMED'?'Участники':'Отклонённые заявки'}</h2></div>${e.participants.filter(p=>p.status===status).map(p=>`<div class="my-row">${avatar(p.user,'warm')}<div><h3><a href="#/people/${p.user}">${esc(person(p.user).name)}</a></h3><p class="small">${status==='PENDING'?'Ожидает твоего решения':status==='CONFIRMED'?'Участие подтверждено':'Участие не подтверждено'}</p></div>${status==='PENDING'?`<div style="margin-left:auto;display:flex;gap:8px;flex-wrap:wrap"><button class="btn secondary" data-action="decision" data-id="${e.id}" data-user="${p.user}" data-status="REJECTED">Отклонить</button><button class="btn" data-action="decision" data-id="${e.id}" data-user="${p.user}" data-status="CONFIRMED">Принять</button></div>`:''}</div>`).join('')||'<p class="muted small">Пока никого.</p>'}</section>`).join('')}</div>`;
  }
  function render() {
    const route=getRoute(), parts=route.pathname.split('/').filter(Boolean);
    renderChrome(route);
    let html, title='Рядом';
    if(route.pathname==='/') html=home();
    else if(route.pathname==='/events') {html=catalog(route);title='Встречи';}
    else if(route.pathname==='/events/new') {html=createPage();title='Новая встреча';}
    else if(parts[0]==='events'&&eventById(parts[1])) {const e=eventById(parts[1]);html=parts[2]==='manage'?manage(e):eventPage(e);title=e.title;}
    else if(parts[0]==='people'&&state.data.people[parts[1]]) {html=profile(parts[1]);title=person(parts[1]).name;}
    else if(route.pathname==='/organizations/temp') {html=profile('anna',true);title='Сообщество «Темп»';}
    else if(route.pathname==='/me'||route.pathname==='/me/events') {html=myPage(route);title=route.pathname==='/me'?'Профиль':'Мои встречи';}
    else html=`<div class="container page">${empty('Страница не найдена','Вернись в каталог, чтобы найти подходящую встречу.')}</div>`;
    main.innerHTML=html; document.title=`${title} — Рядом · прототип`;
  }
  function closeModal() {modal.close();}
  function openLogin() {
    state.returnTo=getRoute().pathname+getRoute().search;
    modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">Встречаемся Рядом</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><p class="modal-note">Выбери профиль для просмотра макета. Данные вымышлены, изменения сохраняются до перезагрузки.</p><div class="login-options">${[['alex','Участник'],['anna','Автор встреч · сообщество «Темп»']].map(([id,label])=>`<button class="login-option" data-action="choose-profile" data-id="${id}">${avatar(id,'warm')}<span><strong>${esc(person(id).name)}</strong><small>${label}</small></span>${icon('arrow')}</button>`).join('')}</div><button class="text-link" style="background:none;margin-top:14px" data-action="register">Создать свой демопрофиль ${icon('arrow')}</button>`;
    modal.showModal();
  }
  function collectDraft(form) {for(const [key,value] of new FormData(form)) state.draft[key]=String(value);}
  document.addEventListener('input',event=>{const form=event.target.closest('form');if(form?.dataset.form==='create')collectDraft(form);if(form?.dataset.form==='question')state.questions[form.dataset.event]=form.elements.body.value;});
  document.addEventListener('change',event=>{
    const el=event.target, action=el.dataset.action;
    if(action==='screen'){state.preview='DEFAULT';go(el.value);}
    else if(action==='preview'){state.preview=el.value;if(['PENDING','CONFIRMED','REJECTED'].includes(el.value)||el.value==='UNPUBLISHED'&&!state.actor)state.actor='alex';render();}
    else if(action==='draft-sport'){collectDraft(el.form);render();}
    else if(el.closest('[data-form="filters"]')){const route=getRoute(), data=new FormData(el.form);for(const key of ['sport','mode','day']){const value=data.get(key);if(value)route.searchParams.set(key,value);else route.searchParams.delete(key);}go('/events'+(route.search?'?'+route.searchParams.toString():''));}
  });
  document.addEventListener('click',event=>{
    const link=event.target.closest('a');
    if(link?.classList.contains('skip-link')){event.preventDefault();main.focus();main.scrollIntoView();return;}
    if(link?.getAttribute('href')?.startsWith('#/')&&getRoute().pathname==='/events/new'&&state.draft.title){event.preventDefault();go(link.getAttribute('href').slice(1));return;}
    const control=event.target.closest('[data-action]');if(!control||control.tagName==='SELECT')return;
    const action=control.dataset.action, id=control.dataset.id;
    if(action==='login')openLogin();
    else if(action==='close-modal')closeModal();
    else if(action==='choose-profile'){if(state.actor&&state.actor!==id){state.draft={};state.step=1;state.questions={};}state.actor=id;state.preview='DEFAULT';closeModal();render();notify(`Демопрофиль: ${person(id).name}`);}
    else if(action==='leave-form'){state.draft={};state.step=1;closeModal();go(control.dataset.path);}
    else if(action==='logout'){state.actor=null;state.draft={};state.questions={};state.step=1;state.preview='DEFAULT';go('/');notify('Вы вышли из демопрофиля');}
    else if(action==='register'){modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">Давай познакомимся</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><p class="modal-note" style="margin-bottom:22px">Создай вымышленный профиль для просмотра макета. Пароль и почта не нужны.</p><form data-form="register"><label class="field"><span>Как тебя зовут?</span><input name="name" required maxlength="120" autocomplete="off" placeholder="Твоё имя"></label><button class="btn wide" type="submit">Продолжить ${icon('arrow')}</button></form>`;modal.querySelector('input').focus();}
    else if(action==='join'){if(!state.actor){openLogin();return;}const e=eventById(id);if(!ownParticipation(e)){e.participants.push({user:state.actor,status:e.mode==='OPEN'?'CONFIRMED':'PENDING'});}state.preview='DEFAULT';render();notify(e.mode==='OPEN'?'Ты в списке участников':'Заявка отправлена организатору');}
    else if(action==='retry'){state.preview='DEFAULT';render();}
    else if(action==='clear-filters')go('/events');
    else if(action==='step-back'){collectDraft(control.form);state.step=Math.max(1,state.step-1);render();scrollTo({top:0,behavior:'smooth'});}
    else if(action==='decision'){const e=eventById(id);if(state.actor!==e.owner)return;const p=e.participants.find(p=>p.user===control.dataset.user);if(p?.status==='PENDING'){p.status=control.dataset.status;render();notify(p.status==='CONFIRMED'?'Участие подтверждено':'Заявка отклонена');}}
    else if(action==='reset'){state.data=JSON.parse(JSON.stringify(initial));state.actor=null;state.preview='DEFAULT';state.draft={};state.step=1;state.questions={};closeModal();go('/');notify('Макет возвращён в начальное состояние');}
  });
  document.addEventListener('submit',event=>{
    const form=event.target;if(!form.dataset.form)return;event.preventDefault();
    const data=new FormData(form);
    if(form.dataset.form==='search'){const q=new URLSearchParams();if(data.get('q')?.trim())q.set('q',data.get('q').trim());if(data.get('city')?.trim())q.set('city',data.get('city').trim());go('/events'+(q.size?'?'+q:''));}
    else if(form.dataset.form==='question'){const body=String(data.get('body')).trim();if(!body){form.elements.body.setCustomValidity('Напиши вопрос');form.elements.body.reportValidity();form.elements.body.setCustomValidity('');return;}state.questions[form.dataset.event]=body;if(!state.actor){openLogin();return;}const e=eventById(form.dataset.event);e.messages.push({user:state.actor,body,time:new Intl.DateTimeFormat('ru',{hour:'2-digit',minute:'2-digit'}).format(new Date())});state.questions[e.id]='';const y=scrollY;render();scrollTo(0,y);notify('Вопрос добавлен в обсуждение макета');}
    else if(form.dataset.form==='register'){const name=String(data.get('name')).trim();if(!name){form.elements.name.setCustomValidity('Напиши имя');form.elements.name.reportValidity();form.elements.name.setCustomValidity('');return;}const id='demo-'+Date.now();state.data.people[id]={name,initials:name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()};state.actor=id;state.draft={};state.questions={};state.step=1;closeModal();render();notify('Демопрофиль создан');}
    else if(form.dataset.form==='create'){
      collectDraft(form);
      if(state.step===1){const when=new Date(`${state.draft.date}T${state.draft.time}:00+07:00`);if(!Number.isFinite(when.getTime())||when<=new Date()){form.elements.date.setCustomValidity('Выбери дату и время в будущем');form.elements.date.reportValidity();form.elements.date.setCustomValidity('');return;}for(const key of ['title','description','city','place',...(state.draft.sport==='custom'?['customSport']:[])]){if(!state.draft[key]?.trim()){form.elements[key].setCustomValidity('Заполни поле');form.elements[key].reportValidity();form.elements[key].setCustomValidity('');return;}}}
      if(state.step<3){state.step++;render();scrollTo({top:0,behavior:'smooth'});}else{const e=draftEvent();e.id='demo-'+Date.now();state.data.events.unshift(e);state.draft={};state.step=1;go('/events/'+e.id);notify('Встреча добавлена в каталог макета');}
    }
  });
  window.addEventListener('hashchange',()=>{state.preview='DEFAULT';render();scrollTo(0,0);});
  window.addEventListener('beforeunload',event=>{if(getRoute().pathname==='/events/new'&&state.draft.title){event.preventDefault();event.returnValue='';}});
  render();
})();
